#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(ggplot2);library(patchwork);library(scales)})
args <- commandArgs(trailingOnly=TRUE);root <- if(length(args)) args[[1]] else Sys.getenv("EASYPSEUDOGENE_BENCHMARK_ROOT",unset=getwd());outdir <- file.path(root,"phase3_publication_figures");dir.create(outdir,showWarnings=FALSE,recursive=TRUE)
tier <- read.delim(file.path(root,"EasyPseudogene_PHASE3_tier_metrics.tsv"),check.names=FALSE);if(any(tier$matching_policy!="one_to_one_maximum_cardinality"))stop("matching policy mismatch")
loso <- read.delim(file.path(root,"EasyPseudogene_PHASE3_LOSO_metrics.tsv"));runtime <- read.delim(file.path(root,"EasyPseudogene_PHASE3_runtime.tsv"))
sp <- c(TAIR10="A. thaliana",Rice="O. sativa",Alyrata="A. lyrata");tier$species <- factor(sp[tier$species],levels=c("A. thaliana","O. sativa","A. lyrata"));tier$tier <- factor(tier$tier,levels=c("sensitive","miniprot_supported","strict_core_disruption","subtype_candidates"),labels=c("Sensitive","Miniprot-supported","Strict core","Subtype"));cols <- c("Sensitive"="#4C78A8","Miniprot-supported"="#59A14F","Strict core"="#E15759","Subtype"="#B07AA1")
theme_pub <- theme_bw(base_size=10)+theme(panel.grid.minor=element_blank(),panel.grid.major.x=element_blank(),legend.position="bottom",legend.title=element_blank(),plot.title=element_text(face="bold",hjust=.5),axis.title=element_text(face="bold"))
a <- ggplot(subset(tier,threshold=="1bp"),aes(species,f1,fill=tier))+geom_col(position=position_dodge(.75),width=.68)+scale_fill_manual(values=cols)+scale_y_continuous(limits=c(0,.56),labels=number_format(accuracy=.01))+labs(title="A  Evidence tiers across species",x=NULL,y="F1 (>=1 bp)")+theme_pub
b <- ggplot(subset(tier,tier=="Strict core"),aes(species,f1,fill=threshold))+geom_col(position=position_dodge(.72),width=.65)+scale_fill_manual(values=c("1bp"="#E15759","50"="#F28E2B","80"="#EDC948"),labels=c(">=1 bp",">=50% reciprocal",">=80% reciprocal"))+scale_y_continuous(limits=c(0,.46),labels=number_format(accuracy=.01))+labs(title="B  Strict-core concordance",x=NULL,y="F1")+theme_pub
loso$held_out_species <- factor(c("A. thaliana","O. sativa","A. lyrata"),levels=c("A. thaliana","O. sativa","A. lyrata"));long <- rbind(data.frame(species=loso$held_out_species,metric="AUC",value=loso$roc_auc),data.frame(species=loso$held_out_species,metric="Held-out F1",value=loso$f1));c <- ggplot(long,aes(species,value,fill=metric))+geom_col(position=position_dodge(.7),width=.62)+scale_fill_manual(values=c(AUC="#76B7B2","Held-out F1"="#FF9DA7"))+scale_y_continuous(limits=c(0,.9),labels=number_format(accuracy=.1))+labs(title="C  Leave-one-species-out transfer",x=NULL,y="Metric")+theme_pub
runtime$species <- factor(c("A. thaliana","O. sativa","A. lyrata"),levels=c("A. thaliana","O. sativa","A. lyrata"));d <- ggplot(runtime,aes(runtime_sec,peak_rss_gb,color=species,size=candidates))+geom_point(alpha=.9)+geom_text(aes(label=species),vjust=-1.1,show.legend=FALSE,size=3)+scale_color_manual(values=c("A. thaliana"="#4C78A8","O. sativa"="#F28E2B","A. lyrata"="#59A14F"))+scale_size_continuous(range=c(4,9),labels=comma)+coord_cartesian(xlim=c(60,225),ylim=c(1.4,5.7))+labs(title="D  End-to-end resources",x="Runtime (s)",y="Peak RSS (GB)",size="Candidates")+theme_pub
combined <- (a|b)/(c|d)+plot_annotation(title="EasyPseudogene Phase-3: evidence stratification and cross-species validation",subtitle="One-to-one reference-annotation concordance; tiers are computational evidence categories",theme=theme(plot.title=element_text(face="bold",size=15,hjust=.5),plot.subtitle=element_text(size=10,hjust=.5,color="#444444")))
for(ext in c("png","pdf","svg"))ggsave(file.path(outdir,paste0("phase3_multispecies_evidence_summary.",ext)),combined,width=12,height=8,dpi=if(ext=="png")400 else 300,bg="white")
